      "치과 차트나 예약 프로그램에서 개인 일정과 승인 자료를 가져오려면 제공 업체의 연결 권한과 자료 형식을 확인합니다. 차트의 내부 메모와 환자에게 설명할 문서를 같은 필드로 무조건 공개하지 않습니다. 결제 내역을 표시하려면 실제 결제 원장과 취소·환급 상태를 구분하고 화면의 계획 비용을 이미 결제한 금액으로 해석하지 않게 합니다. 문자 알림에는 민감한 계획 내용을 직접 넣기보다 로그인 후 확인할 경로를 안내하는 방식을 검토합니다. 전자 동의 기능은 문서 조회와 다른 절차이므로 기관이 필요한 본인 확인·서명·보관 요건을 확인한 뒤 별도 범위로 정합니다."
