      "당일 화면에는 방문 대상자, 기준 날짜와 마지막 갱신 상태를 함께 표시합니다. 장소 안내는 건물·층·공간 이름과 이용 가능한 이동 설명을 제공하며 실내 위치 측정 기능은 필요한 경우에만 별도 검토합니다. 모바일 환자 확인 수단을 사용하는 경우 유효 기간과 재발급 조건을 정하고 화면 캡처 이미지가 계속 사용되지 않도록 처리 방식을 확인합니다. 알림을 거절한 이용자는 앱 안의 변경 목록에서 같은 내용을 볼 수 있어야 합니다. 큰 글자와 화면 읽기 기능에서도 방문자 전환·일정 순서·확인 버튼의 의미가 유지되어야 합니다. 실제 대기 순번을 받을 수 없다면 임의의 예상 순서를 만들어 표시하지 않습니다."
