      "요약 화면은 환자 표현과 자동 정리 문장을 나란히 확인할 수 있도록 구성합니다. 시점과 부정 표현, 약어·숫자와 직접 인용이 필요한 항목을 따로 다루는 출력 규칙을 정합니다. 원문에 없는 사실은 추측해 채우지 않고 확인 필요로 표시하며, 빈칸을 정상이라는 뜻으로 해석하지 않습니다. 입력이 길어 일부만 처리한 경우에는 생략된 범위를 알려 담당자가 불완전한 요약을 전체 기록으로 보지 않게 합니다. 수정된 문장은 검토자의 변경으로 남기고 다시 생성했을 때 승인한 정정이 사라지는지 확인합니다. 출력에 따른 의료 행동을 자동 실행하는 기능은 이 범위에서 분리합니다."
